+func TestParseSameLibraryFromTwoLockfiles(t *testing.T) {
+	input := []byte(`[
+  {
+    "Target": "one/Pipfile.lock",
+    "Type": "pipenv",
+    "Vulnerabilities": [{
+      "VulnerabilityID": "CVE-2020-0001",
+      "PkgName": "requests",
+      "InstalledVersion": "1.0",
+      "FixedVersion": "2.0"
+    }]
+  },
+  {
+    "Target": "two/Pipfile.lock",
+    "Type": "pipenv",
+    "Vulnerabilities": [{
+      "VulnerabilityID": "CVE-2020-0001",
+      "PkgName": "requests",
+      "InstalledVersion": "1.5",
+      "FixedVersion": "2.5"
+    }]
+  }
+]`)
+	result, err := Parse(input, &models.ScanResult{})
+	if err != nil {
+		t.Fatal(err)
+	}
+	fixedIns := result.ScannedCves["CVE-2020-0001"].LibraryFixedIns
+	if len(fixedIns) != 2 {
+		t.Fatalf("got %d library findings, want 2: %#v", len(fixedIns), fixedIns)
+	}
+	want := map[string]struct{ version, fixedIn string }{
+		"one/Pipfile.lock": {"1.0", "2.0"},
+		"two/Pipfile.lock": {"1.5", "2.5"},
+	}
+	for _, fixedIn := range fixedIns {
+		expected, ok := want[fixedIn.Path]
+		if !ok {
+			t.Errorf("unexpected lockfile path: %q", fixedIn.Path)
+			continue
+		}
+		if fixedIn.Name != "requests" || fixedIn.FixedIn != expected.fixedIn {
+			t.Errorf("unexpected finding for %s: %#v", fixedIn.Path, fixedIn)
+		}
+		libraries := result.LibraryScanners.Find(fixedIn.Path, fixedIn.Name)
+		if len(libraries) != 1 || libraries[fixedIn.Path].Version != expected.version {
+			t.Errorf("unexpected library version for %s: %#v", fixedIn.Path, libraries)
+		}
+		delete(want, fixedIn.Path)
+	}
+	if len(want) != 0 {
+		t.Errorf("missing lockfile findings: %#v", want)
+	}
+}
