+func mergeLibraryVulnerability(r *models.ScanResult, vinfo models.VulnInfo) {
+	if r.ScannedCves == nil {
+		r.ScannedCves = models.VulnInfos{}
+	}
+
+	vinfo.Confidences.AppendIfMissing(models.TrivyMatch)
+	existing, ok := r.ScannedCves[vinfo.CveID]
+	if !ok {
+		r.ScannedCves[vinfo.CveID] = vinfo
+		return
+	}
+
+	existing.LibraryFixedIns = append(existing.LibraryFixedIns, vinfo.LibraryFixedIns...)
+	existing.Confidences.AppendIfMissing(models.TrivyMatch)
+	if existing.CveContents == nil {
+		existing.CveContents = models.CveContents{}
+	}
+	for source, content := range vinfo.CveContents {
+		if _, found := existing.CveContents[source]; !found {
+			existing.CveContents[source] = content
+		}
+	}
+	r.ScannedCves[vinfo.CveID] = existing
+}
