--- /dev/null
+++ b/libmanager/libManager_test.go
@@ -0,0 +1,58 @@
+package libmanager
+
+import (
+	"testing"
+
+	"github.com/future-architect/vuls/models"
+)
+
+func TestMergeLibraryVulnerabilityPreservesSources(t *testing.T) {
+	result := &models.ScanResult{
+		ScannedCves: models.VulnInfos{
+			"CVE-2020-0001": {
+				CveID: "CVE-2020-0001",
+				AffectedPackages: models.PackageFixStatuses{
+					{Name: "system-package"},
+				},
+				CveContents: models.CveContents{
+					models.Nvd: {Type: models.Nvd, Summary: "OS advisory"},
+				},
+			},
+		},
+	}
+
+	mergeLibraryVulnerability(result, models.VulnInfo{
+		CveID: "CVE-2020-0001",
+		CveContents: models.CveContents{
+			models.Trivy: {Type: models.Trivy, Summary: "Library advisory"},
+		},
+		LibraryFixedIns: models.LibraryFixedIns{
+			{Path: "/app/one/Pipfile.lock", Name: "requests", FixedIn: "2.20.0"},
+		},
+	})
